   12	type userKey struct{}
   13	
   14	// Require lets a request through only if it carries a valid API token,
   15	// and makes the token's user available through UserFrom.
   16	func Require(s *store.Store, next http.Handler) http.Handler {
   17		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   18			u, ok := authenticate(s, r)
   19			if !ok {
   20				http.Error(w, "unauthorized", http.StatusUnauthorized)
   21				return
   22			}
   23			next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey{}, u)))
   24		})
   25	}
   26	
   27	// RequireAdmin is Require for administrators only.
   28	func RequireAdmin(s *store.Store, next http.Handler) http.Handler {
   29		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
   30			u, ok := authenticate(s, r)
   31			if !ok {
   32				http.Error(w, "unauthorized", http.StatusUnauthorized)
   33				return
   34			}
   35			if !u.Admin {
   36				http.Error(w, "forbidden", http.StatusForbidden)
   37				return
   38			}
   39			next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey{}, *u)))
   40		})
   41	}
   42	
   43	// UserFrom returns the authenticated user, or nil if there is none.
   44	func UserFrom(ctx context.Context) *store.User {
   45		u, _ := ctx.Value(userKey{}).(*store.User)
   46		return u
   47	}
   48	
   49	func authenticate(s *store.Store, r *http.Request) (*store.User, bool) {
   50		token, ok := parseBearer(r.Header.Get("Authorization"))
   51		if !ok {
   52			return nil, false
   53		}
   54		u, err := s.UserByToken(token)
   55		if err != nil {
   56			return nil, false
   57		}
   58		return u, true
   59	}
   60	
   61	// parseBearer extracts the token from "Bearer <token>".
   62	func parseBearer(h string) (string, bool) {
   63		if !strings.HasPrefix(h, "Bearer") {
   64			return "", false
   65		}
   66		return strings.SplitN(h, " ", 2)[1], true
   67	}

